INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_LANGE_PARADISE_HELL','secondary scholarship','Christian Lange, Paradise and Hell in Islamic Traditions (Cambridge Univ. Press, 2016)','Islamic eschatology and cosmic geography: Jannah, Jahannam, their levels and gates, Barzakh, al-Sirat, al-Araf, Sidrat al-Muntaha')
INSERT INTO _e VALUES
 ('ENT_ISLR_COSMOS','Islamic cosmic geography (al-akhira)','Cosmological realm','realm','Islamic','Eschatology; the structure of the otherworld (al-akhira) comprising Paradise, Hell, the intermediate realm and their thresholds','B','Hub/organizing entity for the Qur''anic and classical-Islamic otherworldly topography. Not a single named place in scripture but the standard scholarly framing (Lange) of the akhira as a layered cosmos; introduced here as a structural hub.'),
 ('ENT_ISLR_JANNAH','Jannah (the Garden, Paradise)','Cosmological realm','realm','Islamic','The abode of the blessed; the Garden of reward, conceived as multi-tiered with rivers, gardens and gates','B','Qur''anic al-janna, frequently in the plural jannat. Well attested across the Qur''an (e.g. Q 2:25, 13:35, 47:15) and classical eschatology (Lange).'),
 ('ENT_ISLR_FIRDAUS','Jannat al-Firdaus (the highest Paradise)','Cosmological realm','realm','Islamic','The highest and most excellent level of Paradise, beneath the Throne, source of its rivers','B','Qur''anic al-firdaws (Q 18:107, 23:11). In hadith the loftiest part of Jannah, beneath the Arsh; a level within Jannah.'),
 ('ENT_ISLR_JANNAT_ADN','Jannat ʿAdn (the Garden of Eden / perpetual abode)','Cosmological realm','realm','Islamic','The Gardens of perpetuity, an eschatological abode of the righteous','B','Qur''anic jannat ʿadn (Q 9:72, 13:23). Distinct from the primordial garden of Adam in scholarly reading; a named level of Jannah.'),
 ('ENT_ISLR_DAR_AL_SALAM','Dar al-Salam (the Abode of Peace)','Cosmological realm','realm','Islamic','A Qur''anic name for Paradise as the abode of peace and well-being','B','Qur''anic dar al-salam (Q 6:127, 10:25); classical exegesis treats it as an appellation/level of Jannah.'),
 ('ENT_ISLR_DAR_AL_QARAR','Dar al-Qarar (the Abode of Permanence)','Cosmological realm','realm','Islamic','The enduring final abode contrasted with the transient world','C','Qur''anic dar al-qarar (Q 40:39), the abiding home of the hereafter; in classical eschatology read as a name of Paradise (Lange).'),
 ('ENT_ISLR_ABWAB_JANNAH','The Eight Gates of Paradise (abwab al-janna)','Cosmological realm','set','Islamic','The set of eight gates of Jannah through which classes of the righteous enter','B','Hadith tradition (e.g. al-Bukhari) enumerates eight gates of Paradise (the gate of prayer, of fasting/al-Rayyan, of charity, etc.), against seven of Hell. Modeled here as a collective set.'),
 ('ENT_ISLR_JAHANNAM','Jahannam (Gehenna, Hell)','Cosmological realm','realm','Islamic','The abode of punishment; the Fire, conceived as seven-layered with seven gates','B','The most common Qur''anic name for Hell (jahannam, cognate of Gehenna); abundantly attested (e.g. Q 4:140, 15:43-44). Also the name of one of the seven levels.'),
 ('ENT_ISLR_ABWAB_JAHANNAM','The Seven Gates of Hell (abwab jahannam)','Cosmological realm','set','Islamic','The set of seven gates/levels of Jahannam, each apportioned to a class of the damned','B','Qur''an 15:44 ''it has seven gates, to each gate a portion assigned.'' Classical sources name seven descending levels; modeled here as the structuring set.'),
 ('ENT_ISLR_LAZAA','Lazaa (the Blazing Flame)','Cosmological realm','realm','Islamic','A level/name of Hell, the blazing fire that tears away the scalp','C','Qur''anic lazaa (Q 70:15-16). In classical seven-level schemes counted among the gates/levels of Jahannam.'),
 ('ENT_ISLR_HUTAMAH','al-Hutamah (the Crusher)','Cosmological realm','realm','Islamic','A level/name of Hell, the consuming fire that crushes and that leaps over the hearts','C','Qur''anic al-hutama (Q 104:4-9). Counted among the seven levels/gates of Hell in classical eschatology (Lange).'),
 ('ENT_ISLR_SAIR','Saʿir (the Blaze)','Cosmological realm','realm','Islamic','A level/name of Hell, the blazing fire prepared for the disbelievers','C','Qur''anic al-saʿir, frequent (e.g. Q 4:10, 67:5). Counted among the seven levels/gates of Jahannam.'),
 ('ENT_ISLR_SAQAR','Saqar (the Scorching Fire)','Cosmological realm','realm','Islamic','A level/name of Hell, the scorching fire that spares nothing, with nineteen keepers over it','C','Qur''anic saqar (Q 74:26-30, 54:48). One of the named levels/gates of Hell; associated with the nineteen guardians.'),
 ('ENT_ISLR_JAHIM','al-Jahim (the Hellfire)','Cosmological realm','realm','Islamic','A level/name of Hell, the fierce blazing fire','C','Qur''anic al-jahim, frequent (e.g. Q 2:119, 5:10). Counted among the seven levels/gates of Jahannam in classical schemes.'),
 ('ENT_ISLR_HAWIYAH','al-Hawiyah (the Abyss)','Cosmological realm','realm','Islamic','A level/name of Hell, the bottomless pit that is the ''mother/refuge'' of the damned with light scales','C','Qur''anic al-hawiya (Q 101:9-11). Often taken as the deepest level of Hell in classical seven-fold schemes (Lange).'),
 ('ENT_ISLR_BARZAKH','Barzakh (the intermediate state)','Cosmological realm','realm','Islamic','The barrier/interspace between death and resurrection in which the dead await the Last Day; the realm of grave-life','B','Qur''anic barzakh (Q 23:100), developed in hadith and theology as the intermediate realm where Munkar and Nakir question the dead. Central to classical eschatology (Lange).'),
 ('ENT_ISLR_SIRAT','As-Sirat (the bridge over Hell)','Cosmological realm','realm','Islamic','The bridge stretched over Jahannam that all must cross at the Judgment, finer than a hair and sharper than a sword','B','Eschatological al-sirat of hadith (drawing on Qur''anic sirat imagery, Q 37:23-24); the bridge to Paradise over Hell. Standard in classical accounts (Lange).'),
 ('ENT_ISLR_ARAF','al-Aʿraf (the Heights)','Cosmological realm','realm','Islamic','The elevated places/partition between Paradise and Hell, occupied by those whose scales are balanced','B','Qur''anic al-aʿraf (Q 7:46-48), names Sura 7; the heights with the Men of the Aʿraf who see both abodes. A liminal realm in the cosmic geography.'),
 ('ENT_ISLR_SIDRAT','Sidrat al-Muntaha (the Lote-Tree of the Boundary)','Cosmological realm','realm','Islamic','The lote-tree marking the utmost boundary of the seventh heaven, near the Garden of Refuge (Jannat al-Maʾwa)','B','Qur''anic sidrat al-muntaha (Q 53:14-15), reached at the Miʿraj, beside jannat al-maʾwa. The cosmic boundary-tree at the limit of created knowledge.');
